37	// Skeleton shown during page-to-page navigation transitions inside the app shell.
38	// useNavigation must be called inside PolarisAppProvider so Polaris context is available.
39	function AppContent() {
40	  const navigation = useNavigation();
41	  const isNavigating = navigation.state === "loading";
42	
43	  if (isNavigating) {
44	    return (
45	      <SkeletonPage primaryAction>
46	        <Layout>
47	          <Layout.Section>
48	            <Card>
49	              <SkeletonDisplayText size="small" />
50	              <SkeletonBodyText lines={3} />
51	            </Card>
52	          </Layout.Section>
53	          <Layout.Section>
54	            <Card>
55	              <SkeletonBodyText lines={6} />
56	            </Card>
57	          </Layout.Section>
58	          <Layout.Section>
59	            <Card>
60	              <SkeletonBodyText lines={4} />
61	            </Card>
62	          </Layout.Section>
63	        </Layout>
64	      </SkeletonPage>
65	    );
66	  }
67	
68	  return <Outlet />;
69	}
