71	function ChatwootWidget({ token }: { token: string }) {
72	  useEffect(() => {
73	    if (!token || window.$chatwoot) return;
74	
75	    window.chatwootSettings = {
76	      position: "right",
77	      type: "standard",
78	      launcherTitle: "",
79	    };
80	
81	    const BASE_URL = "https://app.chatwoot.com";
82	    const script = document.createElement("script");
83	    script.src = `${BASE_URL}/packs/js/sdk.js`;
84	    script.async = true;
85	    script.onload = () => {
86	      window.chatwootSDK?.run({
87	        websiteToken: token,
88	        baseUrl: BASE_URL,
89	      });
90	    };
91	    document.body.appendChild(script);
92	  }, [token]);
93	
94	  return null;
95	}
