103	        <ChatwootWidget token={chatwootToken} />
104	        <NavMenu>
105	          <a href="/app">Dashboard</a>
106	          <a href="/app/analytics">Analytics</a>
107	          <a href="/app/zip-codes">Zip Codes</a>
108	          <a href="/app/delivery-rules">Delivery Rules</a>
109	          <a href="/app/widget">Widget</a>
110	          <a href="/app/waitlist">Waitlist</a>
111	          <a href="/app/settings">Settings</a>
112	        </NavMenu>
113	        <AppContent />
