29	  const shop = session.shop;
30	
31	  const [totalZips, allowedZips, blockedZips, deliveryRulesCount, waitlistCount, subscription] = await Promise.all([
32	    db.zipCode.count({ where: { shop } }),
33	    db.zipCode.count({ where: { shop, type: "allowed" } }),
34	    db.zipCode.count({ where: { shop, type: "blocked" } }),
35	    db.deliveryRule.count({ where: { shop } }),
36	    db.waitlistEntry.count({ where: { shop } }),
37	    getShopSubscription(shop),
38	  ]);
39	
40	  const stats = {
41	    total: totalZips,
42	    allowed: allowedZips,
43	    blocked: blockedZips,
44	    deliveryRules: deliveryRulesCount,
45	    waitlist: waitlistCount,
