24	type ResultType = "allowed" | "blocked" | "not_found" | "defaulted_allow";
25	
26	interface LogEntry {
27	  id: string;
28	  zipCode: string;
29	  result: ResultType;
30	  productId: string | null;
31	  createdAt: string;
32	}
33	
34	interface TopDemandedZip {
35	  zipCode: string;
36	  count: number;
37	}
38	
39	export const loader = async ({ request }: LoaderFunctionArgs) => {
40	  const { session } = await authenticate.admin(request);
41	  const shop = session.shop;
42	
43	  const url = new URL(request.url);
44	  const daysParam = url.searchParams.get("days") ?? "7";
45	  const days = daysParam === "all" ? null : parseInt(daysParam, 10) || 7;
46	
47	  const subscription = await getShopSubscription(shop);
48	  const limits = subscription.limits;
49	
50	  if (!limits.zipLogs) {
51	    return {
52	      hasAccess: false,
53	      planLabel: limits.label,
54	      days: daysParam,
55	      totalChecks: 0,
56	      allowedChecks: 0,
57	      blockedChecks: 0,
58	      notFoundChecks: 0,
59	      defaultedChecks: 0,
60	      successRate: 0,
61	      topDemanded: [] as TopDemandedZip[],
62	      recentLogs: [] as LogEntry[],
63	    };
64	  }
65	
66	  const since = days ? new Date(Date.now() - days * 86_400_000) : null;
67	  const baseWhere = since
68	    ? { shop, createdAt: { gte: since } }
69	    : { shop };
70	
71	  const [
72	    totalChecks,
73	    allowedChecks,
74	    blockedChecks,
75	    notFoundChecks,
76	    defaultedChecks,
77	    topDemandedRaw,
78	    recentLogsRaw,
79	  ] = await Promise.all([
80	    db.zipCheckLog.count({ where: baseWhere }),
81	    db.zipCheckLog.count({ where: { ...baseWhere, result: "allowed" } }),
82	    db.zipCheckLog.count({ where: { ...baseWhere, result: "blocked" } }),
83	    db.zipCheckLog.count({ where: { ...baseWhere, result: "not_found" } }),
84	    db.zipCheckLog.count({ where: { ...baseWhere, result: "defaulted_allow" } }),
85	    db.zipCheckLog.groupBy({
86	      by: ["zipCode"],
87	      where: { ...baseWhere, result: { in: ["not_found", "blocked"] } },
88	      _count: { zipCode: true },
89	      orderBy: { _count: { zipCode: "desc" } },
90	      take: 10,
91	    }),
92	    db.zipCheckLog.findMany({
93	      where: baseWhere,
94	      orderBy: { createdAt: "desc" },
95	      take: 200,
96	      select: { id: true, zipCode: true, result: true, productId: true, createdAt: true },
97	    }),
98	  ]);
99	
100	  const successRate =
101	    totalChecks > 0
102	      ? Math.round(((allowedChecks + defaultedChecks) / totalChecks) * 100)
103	      : 0;
104	
105	  return {
106	    hasAccess: true,
107	    planLabel: limits.label,
108	    days: daysParam,
109	    totalChecks,
110	    allowedChecks,
111	    blockedChecks,
112	    notFoundChecks,
113	    defaultedChecks,
114	    successRate,
115	    topDemanded: topDemandedRaw.map((r) => ({
116	      zipCode: r.zipCode,
117	      count: r._count.zipCode,
118	    })) as TopDemandedZip[],
119	    recentLogs: recentLogsRaw.map((l) => ({
120	      ...l,
121	      createdAt: l.createdAt.toISOString(),
122	    })) as LogEntry[],
123	  };
124	};
125	
126	function resultBadge(result: ResultType) {
127	  switch (result) {
128	    case "allowed":
129	      return <Badge tone="success">Allowed</Badge>;
130	    case "defaulted_allow":
131	      return <Badge tone="info">Allowed (default)</Badge>;
132	    case "blocked":
133	      return <Badge tone="critical">Blocked</Badge>;
134	    case "not_found":
135	      return <Badge tone="warning">Not Found</Badge>;
136	  }
137	}
