139	function timeAgo(isoString: string): string {
140	  const diff = Date.now() - new Date(isoString).getTime();
141	  const mins = Math.floor(diff / 60_000);
142	  if (mins < 1) return "just now";
143	  if (mins < 60) return `${mins}m ago`;
144	  const hrs = Math.floor(mins / 60);
145	  if (hrs < 24) return `${hrs}h ago`;
146	  const days = Math.floor(hrs / 24);
147	  return `${days}d ago`;
148	}
