47	export const loader = async ({ request }: LoaderFunctionArgs) => {
48	  const { session, admin } = await authenticate.admin(request);
49	  const shop = session.shop;
50	
51	  const [subscription, zipCount, deliveryRuleCount, waitlistCount, blockedZipCount, shopSettings, shopResponse] = await Promise.all([
52	    getShopSubscription(shop),
53	    db.zipCode.count({ where: { shop } }),
54	    db.deliveryRule.count({ where: { shop } }),
55	    db.waitlistEntry.count({ where: { shop } }),
56	    db.zipCode.count({ where: { shop, type: "blocked" } }),
57	    db.shopSettings.findUnique({ where: { shop } }),
58	    admin.graphql(`{ shop { name } }`),
59	  ]);
60	
61	  const shopData = await shopResponse.json() as { data?: { shop?: { name?: string } } };
62	  const shopName: string = shopData.data?.shop?.name ?? shop.replace(".myshopify.com", "");
63	
64	  await db.shopSettings.upsert({
65	    where: { shop },
66	    create: { shop, shopName },
67	    update: { shopName },
68	  });
69	
70	  return {
71	    subscription,
72	    zipCount,
73	    deliveryRuleCount,
74	    waitlistCount,
75	    blockedZipCount,
76	    shop,
77	    shopName,
78	    defaultBehavior: shopSettings?.defaultBehavior ?? "block",
79	    notificationEmail: shopSettings?.notificationEmail ?? "",
80	    emailSenderName: shopSettings?.emailSenderName ?? "",
81	    emailReplyTo: shopSettings?.emailReplyTo ?? "",
82	  };
83	};
