87	// ---------------------------------------------------------------------------
88	
89	export const action = async ({ request }: ActionFunctionArgs) => {
90	  const { session } = await authenticate.admin(request);
91	  const shop = session.shop;
92	
93	  const formData = await request.formData();
94	  const intent = formData.get("intent") as string;
95	
96	  try {
97	    if (intent === "save-behavior") {
98	      const defaultBehavior = formData.get("defaultBehavior") as string;
99	      if (defaultBehavior !== "block" && defaultBehavior !== "allow") {
100	        return { error: "Invalid value for defaultBehavior" };
101	      }
102	      await db.shopSettings.upsert({
103	        where: { shop },
104	        create: { shop, defaultBehavior },
105	        update: { defaultBehavior },
106	      });
107	      return { success: true, intent };
108	    }
109	
110	    if (intent === "save-notification") {
111	      const notificationEmail =
112	        (formData.get("notificationEmail") as string | null) ?? "";
113	      await db.shopSettings.upsert({
114	        where: { shop },
115	        create: { shop, notificationEmail: notificationEmail || null },
116	        update: { notificationEmail: notificationEmail || null },
117	      });
118	      return { success: true, intent };
119	    }
120	
121	    if (intent === "save-email-settings") {
122	      const emailSenderName =
123	        (formData.get("emailSenderName") as string | null)?.trim() || null;
124	      const emailReplyTo =
125	        (formData.get("emailReplyTo") as string | null)?.trim() || null;
126	      await db.shopSettings.upsert({
127	        where: { shop },
128	        create: { shop, emailSenderName, emailReplyTo },
129	        update: { emailSenderName, emailReplyTo },
130	      });
131	      return { success: true, intent };
132	    }
133	
134	    if (intent === "send-test-email") {
135	      const testEmail = (formData.get("testEmail") as string | null) ?? "";
136	      if (!testEmail) return { error: "No email address provided." };
137	      if (!isEmailConfigured()) {
138	        return { error: "Email is not configured — RESEND_API_KEY environment variable is missing. Add it to your .env file and redeploy." };
139	      }
140	      const settings = await db.shopSettings.findUnique({ where: { shop } });
141	      const sent = await sendTestEmail(
142	        testEmail,
143	        { senderName: settings?.emailSenderName, shopDisplayName: settings?.shopName, replyTo: settings?.emailReplyTo },
144	        shop,
145	      );
146	      return sent
147	        ? { success: true, intent }
148	        : { error: "Failed to send test email via Resend. Verify your RESEND_API_KEY is valid and your sender domain is verified in the Resend dashboard." };
149	    }
150	
151	    return { error: "Unknown intent" };
152	  } catch {
153	    return { error: "Failed to save settings. Please try again." };
154	  }
155	};
