212	      create: { shop, planId, billingInterval: "monthly", status: "active" },
213	      update: { planId, billingInterval: "monthly", status: "active", shopifySubscriptionId: null },
214	    });
215	    return { success: true, message: `Plan set to ${tier.charAt(0).toUpperCase() + tier.slice(1)}.` };
216	  }
217	
218	  if (intent === "cancel") {
219	    try {
220	      const sub = await getShopSubscription(shop);
221	      if (sub.shopifySubscriptionId) {
222	        await billing.cancel({
223	          subscriptionId: sub.shopifySubscriptionId,
224	          isTest: process.env.NODE_ENV !== "production",
225	          prorate: true,
226	        });
227	      }
228	      await cancelShopSubscription(shop);
229	      return {
230	        success: true,
231	        message: "Subscription cancelled. You are now on the Free plan.",
232	      };
233	    } catch {
234	      return { error: "Failed to cancel subscription. Please try again." };
235	    }
236	  }
237	
238	  return null;
