61	export const loader = async ({ request }: LoaderFunctionArgs) => {
62	  const { session, admin } = await authenticate.admin(request);
63	  const shop = session.shop;
64	
65	  // Check if merchant has approved read_products scope
66	  const hasProductScope = session.scope?.includes("read_products") ?? false;
67	
68	  const [rules, zones, subscription] = await Promise.all([
69	    db.deliveryRule.findMany({
70	      where: { shop },
71	      orderBy: { priority: "asc" },
72	    }),
73	    db.zipCode.findMany({
74	      where: { shop, zone: { not: null } },
75	      select: { zone: true },
76	      distinct: ["zone"],
77	    }),
78	    getShopSubscription(shop),
79	  ]);
80	
81	  // Batch-fetch names for rules that target specific products or collections
82	  let productNames: Record<string, string> = {};
83	  let collectionNames: Record<string, string> = {};
84	
85	  if (hasProductScope) {
86	    const allProductIds = new Set<string>();
87	    const allCollectionIds = new Set<string>();
88	
89	    for (const rule of rules) {
90	      if (rule.targetType === "products" && rule.productIds) {
91	        rule.productIds.split(",").forEach((id) => allProductIds.add(id.trim()));
92	      }
93	      if (rule.targetType === "collections" && rule.collectionIds) {
94	        rule.collectionIds
95	          .split(",")
96	          .forEach((id) => allCollectionIds.add(id.trim()));
97	      }
98	    }
99	
100	    try {
101	      if (allProductIds.size > 0) {
102	        const productGids = [...allProductIds].map(
103	          (id) => `gid://shopify/Product/${id}`,
104	        );
105	        const response = await admin.graphql(
106	          `#graphql
107	          query ProductNames($ids: [ID!]!) {
108	            nodes(ids: $ids) {
109	              ... on Product {
110	                id
111	                title
112	              }
113	            }
114	          }`,
115	          { variables: { ids: productGids } },
116	        );
117	        const data = (await response.json()) as NodesQueryResponse;
118	        for (const node of data?.data?.nodes ?? []) {
119	          if (node?.id && node?.title) {
120	            const numId = node.id.match(/\/(\d+)$/)?.[1];
121	            if (numId) productNames[numId] = node.title;
122	          }
123	        }
124	      }
125	
126	      if (allCollectionIds.size > 0) {
127	        const collectionGids = [...allCollectionIds].map(
128	          (id) => `gid://shopify/Collection/${id}`,
129	        );
130	        const response = await admin.graphql(
131	          `#graphql
132	          query CollectionNames($ids: [ID!]!) {
133	            nodes(ids: $ids) {
134	              ... on Collection {
135	                id
136	                title
137	              }
138	            }
139	          }`,
140	          { variables: { ids: collectionGids } },
141	        );
142	        const data = (await response.json()) as NodesQueryResponse;
143	        for (const node of data?.data?.nodes ?? []) {
144	          if (node?.id && node?.title) {
145	            const numId = node.id.match(/\/(\d+)$/)?.[1];
146	            if (numId) collectionNames[numId] = node.title;
147	          }
