186	      String(formData.get("estimatedDays") || "").trim() || null;
187	    const cutoffTime =
188	      String(formData.get("cutoffTime") || "").trim() || null;
189	    const daysOfWeek =
190	      String(formData.get("daysOfWeek") || "").trim() || null;
191	    const priority = parseInt(String(formData.get("priority") || "0"), 10);
192	
193	    // Product/Collection targeting fields
194	    const targetType =
195	      (String(formData.get("targetType") || "all") as
196	        | "all"
197	        | "products"
198	        | "collections") || "all";
199	    const productIds =
200	      String(formData.get("productIds") || "").trim() || null;
201	    const collectionIds =
202	      String(formData.get("collectionIds") || "").trim() || null;
203	
204	    if (!name) return { error: "Rule name is required." };
205	
206	    // Plan-gating for product/collection targeting
207	    if (targetType !== "all") {
208	      const subscription = await getShopSubscription(shop);
209	      if (!subscription.limits.productCollectionRules) {
210	        return {
211	          error: `Product and collection targeting requires the Pro plan or higher. Upgrade to use this feature.`,
212	        };
213	      }
214	    }
215	
216	    const data = {
217	      name,
218	      zone,
219	      zipCodes,
220	      minOrderAmount,
221	      deliveryFee,
222	      freeShippingAbove,
223	      estimatedDays,
224	      cutoffTime,
