290	    } catch {
291	      return { error: "Failed to toggle rule." };
292	    }
293	  }
294	
295	  if (intent === "bulk-delete") {
296	    const ids = String(formData.get("ids") || "").split(",").filter(Boolean);
297	    if (ids.length === 0) return { error: "No rules selected." };
298	    try {
299	      await db.deliveryRule.deleteMany({ where: { id: { in: ids }, shop } });
300	      return { success: true, action: "bulk-deleted" };
301	    } catch {
302	      return { error: "Failed to delete rules." };
303	    }
304	  }
305	
306	  if (intent === "bulk-toggle") {
307	    const ids = String(formData.get("ids") || "").split(",").filter(Boolean);
308	    const active = formData.get("active") === "true";
309	    if (ids.length === 0) return { error: "No rules selected." };
